<script setup lang="ts">
import type { Row } from '../../../shared/domain';
import { railwayPlaces, railwayQuestions, railwaySources, railwayDate, safeRailwayUrl, useRailway } from '../../../shared/railway';
const props = defineProps<{ notices: Row[] }>();
const { section, place, expanded, question, articles, filtered, chooseSection } = useRailway(() => props.notices);
let sourceAction = '复制链接';
// #ifdef H5
sourceAction = '查看原文';
// #endif
function openSource(value: string) {
  const url = safeRailwayUrl(value);if (!url) return;
  // #ifdef H5
  window.open(url, '_blank', 'noopener,noreferrer');
  // #endif
  // #ifdef MP-WEIXIN
  uni.setClipboardData({ data: url, fail: () => uni.showToast({title:'复制失败，请重试',icon:'none'}) });
  // #endif
}
function showNews(value = '全部') { chooseSection(value);uni.pageScrollTo({ selector: '#rail-mobile-news', duration: 250 }); }
</script>
<template>
  <view class="railway-hub railway-mobile">
    <view class="rail-page-heading"><view><view class="rail-kicker">家乡新连接 · 淮新高铁专题</view><view class="rail-page-title">一凡说高铁 <text class="hot-badge">HOT</text></view><view class="rail-lead">关心一条路，也关心每一次回家。</view></view><!-- #ifdef MP-WEIXIN --><button class="rail-button rail-outline" open-type="share">分享给老乡 ↗</button><!-- #endif --></view>
    <view class="rail-hero"><view class="rail-hero-copy"><text class="rail-hero-label">和老乡一起，关注家乡高铁</text><view class="rail-hero-title">回家的期待，<view class="rail-gold-text">在这里相遇。</view></view><view class="rail-hero-text">从规划消息到出行关注，<br/>一起读懂淮新高铁，记录家乡的新连接。</view><view class="rail-hero-actions"><button class="rail-button rail-gold" @click="showNews()">查看专题动态 ↓</button><text class="rail-hero-note">资讯有出处 · 观点有标注</text></view></view><image class="rail-art" src="/static/railway-scene.svg" mode="aspectFill"/></view>
    <view class="rail-layout"><view class="rail-card rail-route"><view class="rail-section-head"><view><view class="rail-kicker">沿着家乡，了解更多</view><view class="rail-section-title">三个区域，一份牵挂</view></view><text class="rail-mini-label">区域示意</text></view><view class="rail-route-line"><button v-for="(item,i) in railwayPlaces" :key="item.name" :class="['rail-place',{active:place===i}]" @click="place=i"><view class="rail-point"/><text class="rail-place-name">{{ item.name }}</text><text>{{ item.label }}</text></button></view><view class="rail-place-detail"><view class="rail-detail-title">{{ railwayPlaces[place].name }} · {{ railwayPlaces[place].label }}</view><view class="rail-detail-copy">{{ railwayPlaces[place].text }}</view></view><view class="rail-caption">区域关系示意，非正式站点及施工线路图。</view></view><view class="rail-editorial"><view class="rail-editorial-mark">凡</view><view class="rail-kicker">一个老乡的高铁观察</view><view class="rail-section-title">消息与期待，慢慢聊。</view><view class="rail-editorial-copy">把大家关心的问题讲明白，<br/>把信息的来龙去脉说清楚。</view><button class="rail-button rail-outline" @click="showNews('一凡说高铁')">看看一凡的解读 →</button><view class="rail-caption">个人观察与解读，单独标注。</view></view></view>
    <view id="rail-mobile-news" class="rail-news"><view class="rail-section-head"><view><view class="rail-kicker">消息有来处，关注有方向</view><view class="rail-section-title">专题动态 <text class="rail-total">{{ articles.length }}</text></view></view></view><view class="rail-tabs"><button v-for="item in ['全部','淮新高铁','一凡说高铁']" :key="item" :class="{active:section===item}" @click="chooseSection(item)">{{ item==='淮新高铁' ? '专题资讯' : item==='一凡说高铁' ? '一凡解读' : item }}</button></view><view v-if="!filtered.length" class="rail-empty"><view class="rail-empty-symbol">↗</view><view class="rail-empty-title">{{ section==='一凡说高铁' ? '一凡的高铁观察，正在整理中' : '把值得关注的消息，留在这里' }}</view><view class="rail-empty-copy">{{ section==='一凡说高铁' ? '解读发布后，会在这个栏目与你见面。' : '专题内容发布后将在这里展示，也可以先查看下方的官方信息入口。' }}</view></view><view v-for="item in filtered" :key="item.id" class="rail-article"><view class="rail-article-meta"><text :class="['rail-category',{opinion:item.category==='一凡说高铁'}]">{{ item.category==='一凡说高铁' ? '一凡解读 · 观点' : '专题资讯' }}</text><text>{{ railwayDate(item.sourceDate || item.createdAt) }}</text></view><button class="rail-mobile-article-title" @click="expanded=expanded===item.id ? '' : item.id">{{ item.title }}</button><view :class="['rail-article-copy',{collapsed:expanded!==item.id}]">{{ item.content }}</view><view class="rail-article-bottom"><text>来源：{{ item.sourceName || (item.category==='一凡说高铁' ? '一凡说高铁' : '平台整理') }}</text><view class="rail-mobile-actions"><button v-if="safeRailwayUrl(item.sourceUrl)" class="rail-text-button" @click="openSource(item.sourceUrl)">{{ sourceAction }} ↗</button><button class="rail-text-button" @click="expanded=expanded===item.id ? '' : item.id">{{ expanded===item.id ? '收起' : '阅读全文' }}</button></view></view></view></view>
    <view class="rail-layout rail-bottom"><view class="rail-card"><view class="rail-section-head"><view class="rail-section-title">老乡关心的问题</view></view><view v-for="(item,i) in railwayQuestions" :key="item.question" class="rail-faq"><button :aria-expanded="question===i" @click="question=question===i ? -1 : i"><text>{{ item.question }}</text><text>{{ question===i ? '−' : '＋' }}</text></button><view v-if="question===i" class="rail-faq-answer">{{ item.answer }}</view></view></view><view class="rail-card"><view class="rail-section-head"><view class="rail-section-title">官方信息入口</view></view><button v-for="item in railwaySources" :key="item.url" class="rail-source" @click="openSource(item.url)"><view><view class="rail-source-title">{{ item.title }}</view><view class="rail-source-copy">{{ item.description }}</view></view><text>{{ sourceAction==='复制链接' ? '复制' : '↗' }}</text></button><view class="rail-caption">站点、开工与通车时间，以正式批复及运营公告为准。</view></view></view>
  </view>
</template>
